WITH product_summary AS (SELECT product_id, MAX(unit_price) - MIN(unit_price) AS unit_price_range, COUNT(DISTINCT quantity) AS unique_products FROM order_items WHERE order_id IN (18, 28) GROUP BY product_id) SELECT p.id, p.supplier_id, p.category, ps.unit_price_range, ps.unique_products FROM products p INNER JOIN product_summary ps ON p.id = ps.product_id WHERE ps.unit_price_range > 55;
